spec.expr:
100 *
sum by (container) (
  container_memory_working_set_bytes{
    namespace="$namespace",
    container!="",
    container!="POD"
  }
)
/
sum by (container) (
  kube_pod_container_resource_limits{
    namespace="$namespace",
    resource="memory",
    unit="byte"
  }
)

100 *
sum by (container) (
  rate(container_cpu_usage_seconds_total{
    namespace="$namespace",
    container!="",
    container!="POD"
  }[5m])
)
/
sum by (container) (
  kube_pod_container_resource_limits{
    namespace="$namespace",
    resource="cpu",
    unit="core"
  }
)

max by (component) (
  label_replace(
    (
      kube_deployment_status_replicas_available{
        namespace="$namespace",
        deployment=~"vote|result|worker|redis"
      } > bool 0
    ),
    "component", "$1", "deployment", "(.*)"
  )
  or
  label_replace(
    (
      kube_statefulset_status_replicas_ready{
        namespace="$namespace",
        statefulset="postgres"
      } > bool 0
    ),
    "component", "$1", "statefulset", "(.*)"
  )
)

sum by (container) (
  rate(
    container_cpu_usage_seconds_total{
      namespace="$namespace",
      container!="",
      container!="POD"
    }[5m]
  )
)

sum by (container) (
  container_memory_working_set_bytes{
    namespace="$namespace",
    container!="",
    container!="POD"
  }
)

sum(
  count_over_time(
    {namespace="$namespace"}
    |~ "(?i)error|warning|warn|exception|failed|failure|fatal|panic"
    != "no config file specified, using the default config"
    != "failed to create fsnotify watcher: too many open files"
    [$__range]
  )
) or vector(0)

sum by (container) (
  rate(container_cpu_usage_seconds_total{
    namespace="$namespace",
    container!="",
    container!="POD"
  }[5m])
)

sum by (container) (
  rate(container_cpu_usage_seconds_total{
    namespace="$namespace",
    container!="",
    container!="POD"
  }[5m])
)

sum(
  max by (node) (
    kube_node_status_condition{
      condition="Ready",
      status="true"
    }
  )
  * on(node)
  max by (node) (
    kube_node_role{
      role="control-plane"
    }
  )
)

sum(
  max by (node) (
    kube_node_status_condition{
      condition="Ready",
      status="true"
    }
  )
  * on(node)
  max by (node) (
    kube_node_role{
      role="worker"
    }
  )
)

sum by (container) (
  container_memory_working_set_bytes{
    namespace="$namespace",
    container!="",
    container!="POD"
  }
)
